function hideTraffic(pool,from){for(let i=from;i<pool.length;i++)for(const parts of [...pool[i].cars,...pool[i].bogies.flat()])for(const p of parts)p.show=false;}
function placeBogies(bogies,d,g,show=true){for(let j=0;j<2;j++){const f=surfaceFrame(g,d+[-7.1,7.1][j],.9),q=rotationFor(f),p=lifted(f,.07),matrix=modelMatrix([p.x,p.y,p.z],[q.x,q.y,q.z,q.w]);for(const part of bogies[j]){part.show=show;part.modelMatrix=matrix;}}}
