function updateCity(force=false){if(!viewer)return;const model=window.RAIL_CITY_MODELS;if(!model){$('scene-status').textContent='街モデルを読み込めません。ホームと走行路で運転できます。';return;}const location=C.position(geo,state.distance);if(!force&&cityLastPosition&&Math.hypot((location.lon-cityLastPosition.lon)*90400,(location.lat-cityLastPosition.lat)*111200)<120)return;cityLastPosition=location;const radius=quality===2?1100:700;const needed=quality===0?[]:model.chunks.map(chunk=>({chunk,distance:Math.hypot((chunk.lon-location.lon)*90400,(chunk.lat-location.lat)*111200)})).filter(v=>v.distance<radius).sort((a,b)=>a.distance-b.distance).slice(0,quality===2?24:12);const ids=new Set(needed.map(v=>v.chunk.id));for(const [id,primitive]of cityActive){if(!ids.has(id)){viewer.scene.primitives.remove(primitive);cityActive.delete(id);}}let created=0;for(const {chunk}of needed){if(cityActive.has(chunk.id))continue;if(!force&&created>=2)break;try{cityActive.set(chunk.id,cityChunkPrimitive(chunk));created++;}catch(error){$('scene-status').textContent='一部の街モデルを読み込めません。運転は続けられます。';}}if(cityActive.size<ids.size)cityLastPosition=null;$('scene-status').textContent=quality===0?'３D走行 · 街の表示なし':'着色済みの軽量3D街 · '+cityActive.size+'区画 / 全'+model.chunks.length+'区画';viewer.scene.requestRender();}
function buildings(){cityLastPosition=null;updateCity(true);}
function networkDeadline(promise){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('地形の読み込みがタイムアウトしました。')),25000);promise.then(value=>{clearTimeout(timer);resolve(value);},error=>{clearTimeout(timer);reject(error);});});}
function alignTerrainResolution(provider,level=13){const availability=provider.getTileDataAvailable?.bind(provider),request=provider.requestTileGeometry?.bind(provider);if(availability)provider.getTileDataAvailable=(x,y,z)=>z>level?false:availability(x,y,z);if(request)provider.requestTileGeometry=(x,y,z,r)=>{if(z>level)return undefined;const pending=request(x,y,z,r);if(!pending)return pending;return Promise.resolve(pending).then(data=>{if(z===level)data.isChildAvailable=()=>false;return data;});};return provider;}
async function initialize3D(){if(!window.Cesium){$('scene-status').textContent='３Dの読込に失敗。全線マップで運転できます。';return;}try{Ces=window.Cesium;Ces.Ion.defaultAccessToken='';$('scene-status').textContent='建物と同じ高さ基準の地形を読み込んでいます…';const terrain=await networkDeadline(Ces.CesiumTerrainProvider.fromUrl(D.terrain.url,{requestVertexNormals:true,credit:new Ces.Credit(D.terrain.credit,true)}));alignTerrainResolution(terrain);const models=window.RAIL_PREBUILT_MODELS;if(!models?.groundHeights||!models.tracks?.length||!models.stations?.length)throw new Error('立体モデルを読み込めませんでした。');for(const [key,g]of Object.entries(routeGeometries)){D.routes[key].groundHeights=models.groundHeights[key];C.applyElevation(g,models.groundHeights[key]);C.applyElevation(scenicRoutes[key],models.groundHeights[key]);}const savedState=state;prepareTrip(selectedStart);state=savedState;viewer=new Ces.Viewer('cesium',{creditContainer:$('data-credits'),creditViewport:$('help'),animation:false,timeline:false,baseLayerPicker:false,baseLayer:false,geocoder:false,homeButton:false,sceneModePicker:false,navigationHelpButton:false,fullscreenButton:false,selectionIndicator:false,infoBox:false,terrainProvider:terrain,skyBox:false,skyAtmosphere:new Ces.SkyAtmosphere(),requestRenderMode:true,maximumRenderTimeChange:Infinity,targetFrameRate:30,shouldAnimate:false});viewer.scene.globe.baseColor=Ces.Color.fromCssColorString('#1b5265');viewer.scene.backgroundColor=Ces.Color.fromCssColorString('#b0d6df');viewer.scene.globe.depthTestAgainstTerrain=true;viewer.scene.screenSpaceCameraController.enableCollisionDetection=false;viewer.scene.screenSpaceCameraController.enableInputs=false;viewer.scene.fog.enabled=true;viewer.resolutionScale=renderQuality;viewer.scene.globe.maximumScreenSpaceError=quality===2?4:8;viewer.scene.globe.tileCacheSize=40;viewer.imageryLayers.addImageryProvider(new Ces.UrlTemplateImageryProvider({url:'https://cyberjapandata.gsi.go.jp/xyz/seamlessphoto/{z}/{x}/{y}.jpg',maximumLevel:quality===2?17:15,credit:new Ces.Credit('<a href="https://maps.gsi.go.jp/development/ichiran.html" target="_blank">国土地理院・地理院タイル（加工）</a>',true)}));viewer.scene.frameState;viewer.creditDisplay.addStaticCredit(new Ces.Credit(D.terrain.credit,true));viewer.creditDisplay.addStaticCredit(new Ces.Credit('着色済み街モデル：© OpenStreetMap contributors / ODbL-1.0 · 地形：PLATEAU | Mapterhorn | 国土地理院',true));viewer.scene.renderError.addEventListener(()=>{sceneReady=false;setView('map');$('scene-status').textContent='３D描画を続けられないため全線マップへ切り替えました。';});const tunnelResult=window.BaylineTunnels.setup(viewer,Ces,routeGeometries,surfaceFrame);sceneReady=true;buildRailway();if(!tunnelResult.supported)$('scene-status').textContent='地下の３D表示にはWebGL2が必要です。地下区間はマップで運転できます。';void buildings();setView(view);updateCamera();}catch(error){sceneReady=false;if(viewer){try{viewer.destroy();}catch{}viewer=null;}setView('map');$('scene-status').textContent='地形や３Dを読み込めません。全線マップで運転できます。';}}
function soundHorn(){if(!$('sound').checked){$('sound-status').textContent='警笛を鳴らすには「音・放送」をオンにしてください。';return;}if(enableAudio()){audioController.setVolume(Number($('volume').value)/100);audioController.horn();}}
function enableAudio(){return audioController?.enable()||false;}
function announcementScript(kind){const data=window.RAIL_ANNOUNCEMENTS?.[direction],stop=route.stops[state.next];if(!data||!stop)return null;let segments=[...(data[kind]?.[stop.code]||[])];if(false)segments=segments.map(x=>({...x,text:x.text.replaceAll('各駅停車','快速').replace('Line train for','Line rapid train for')}));if(kind==='next'&&$('temporary-notices').checked)segments.push(...(data.temporary?.[stop.code]||[]));return {segments,recordKey:direction+':'+kind+':'+stop.code};}
function syncDoorSound(){const station=stoppedStation();if(station&&station.index!==selectedStart&&state.elapsed>0){const index=station.index,stop=station.stop;if(stop&&index!==lastStopAnnounced&&audioController?.ready){lastStopAnnounced=index;const segments=window.RAIL_ANNOUNCEMENTS?.[direction]?.arrived?.[stop.code];void audioController.onboard('arrived',stop.name,'',{segments,recordKey:direction+':arrived:'+stop.code},true);}}if(state.doors&&!previousDoors){ensureBoarding();audioController?.doorOpen();}previousDoors=state.doors;}
