async function beginDeparture(){if(state.departureHold||!state.doors||!audioController?.ready)return;const current=state;state.departureHold=true;state.departureReady=false;state.message='発車ベルとドア閉め案内を再生中。';updateUI();let finished=false;try{finished=await audioController.departure(1,{closeDoors:true,introSegments:!greetingDone&&state.visited.length===1?greetingSegments():[]});}catch{}if(current!==state||!state.running||!state.departureHold)return;state.departureReady=true;if(!finished)$('sound-status').textContent='音声案内を完了できなかったため、戸閉確認して運転を続けます。';if(!finalizeDeparture()){state.message='発車準備完了。発車時刻まで停車しています。';updateUI();}}
function formatClock(seconds){seconds=Math.max(0,Math.floor(seconds));return [Math.floor(seconds/3600)%24,Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':');}
function updateTimetableUI(){$('trip-mode').value=tripMode;const panel=$('timetable-panel'),skip=$('skip-wait');panel.hidden=tripMode!=='timetable';if(tripMode!=='timetable'){skip.disabled=true;return;}const index=state.doors?C.platformIndex(state):state.next,entry=state.schedule?.stops[index],stop=route.stops[index];if(!entry)return;$('timetable-station').textContent=stop.name+(state.doors?' 発車':' 到着');const planned=state.doors?entry.departure:entry.arrival;$('scheduled-time').textContent=planned===null?'終点':formatClock(planned);const diff=planned===null?0:Math.round(C.clock(state)-planned);$('timing-status').textContent=planned===null?'終点に到着':diff>0?diff+'秒遅れ':diff<0?'あと '+(-diff)+'秒':'定刻';skip.disabled=!state.doors||boardingPending()||state.complete||planned===null||C.clock(state)>=planned;}
